// Keep only metadata: no message bodies, recipients or secrets leave this node.
const e = $input.first().json;
const safe = {
  at: new Date().toISOString(),
  workflow: e.workflow?.name || 'unknown',
  executionId: e.execution?.id || 'unknown',
  executionUrl: e.execution?.url || null,
  lastNode: e.execution?.lastNodeExecuted || e.trigger?.error?.node?.name || 'unknown',
  message: String(e.execution?.error?.message || e.trigger?.error?.message || 'Unknown workflow error').slice(0, 500),
};
console.error('[LendLoop automation failure]', JSON.stringify(safe));
const to = $env.OPS_ALERT_EMAIL || 'ops@lendloop.local';
return [{ json: { ...safe, mail: {
  From: { Email: 'alerts@lendloop.local', Name: 'LendLoop automations' },
  To: [{ Email: to }],
  Subject: `[LendLoop] ${safe.workflow} failed at "${safe.lastNode}"`,
  Text: [
    `Workflow: ${safe.workflow}`,
    `Failed node: ${safe.lastNode}`,
    `Error: ${safe.message}`,
    `Execution: ${safe.executionUrl || safe.executionId}`,
    `Time: ${safe.at}`,
  ].join('\n'),
} } }];
